// sw.js — service worker: makes Bol load with no internet (airplane mode).
//
// Strategy: "cache first". On install, every file the app needs is downloaded
// into a versioned cache. Afterwards every request is answered from that cache,
// so the network is never needed.
//
// Updates: a new version installs in the background and then WAITS. The app
// shows "Update available — tap to reload"; only when the user taps does the
// new version take over (message SKIP_WAITING). Nothing changes mid-sentence.
//
// The block between BEGIN/END is generated by tools/build_sw.py, which lists
// every app file and sets CACHE_VERSION from a hash of their contents, so the
// version changes automatically whenever any file changes.

// BEGIN GENERATED
const CACHE_VERSION = 'bol-4b8fbf4f50';
const APP_FILES = [
  './',
  './index.html',
  './manifest.webmanifest',
  './css/style.css',
  './js/app.js',
  './js/backup.js',
  './js/caregiver.js',
  './js/i18n.js',
  './js/media.js',
  './js/routines.js',
  './js/speech.js',
  './js/state.js',
  './js/store.js',
  './js/ui.js',
  './js/vocab.js',
  './data/languages.json',
  './data/legacy-v1.json',
  './data/ui.json',
  './data/vocab.json',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/icon.svg',
];
// END GENERATED

self.addEventListener('install', event => {
  event.waitUntil(caches.open(CACHE_VERSION).then(cache => cache.addAll(APP_FILES)));
});

self.addEventListener('message', event => {
  if (event.data && event.data.type === 'SKIP_WAITING') self.skipWaiting();
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k !== CACHE_VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== self.location.origin) return;
  event.respondWith(
    caches.match(req, { ignoreSearch: true }).then(cached => {
      if (cached) return cached;
      return fetch(req)
        .then(res => {
          // Keep a copy of anything new we fetch from our own site.
          if (res.ok) {
            const copy = res.clone();
            caches.open(CACHE_VERSION).then(c => c.put(req, copy));
          }
          return res;
        })
        .catch(() => {
          // Offline and not cached: for page loads, fall back to the app shell.
          if (req.mode === 'navigate') return caches.match('./index.html');
          return new Response('', { status: 504, statusText: 'Offline' });
        });
    })
  );
});
